package org.sleepwell.app;

import org.junit.Test;
import java.time.*;
import java.util.*;
import java.util.stream.*;
import static org.junit.Assert.*;

public class ChartTicksTest {
    private static final ZoneId UTC=ZoneOffset.UTC;private static final Locale US=Locale.US;
    private long at(String value){return Instant.parse(value).toEpochMilli();}
    private List<ChartTicks.Tick> ticks(long start,long end,ZoneId zone){return ChartTicks.candidates(start,end,zone,false,US,5);}
    @Test public void overnightInteriorTicksAreRealWholeHoursNotFractionalElapsedDivisions(){long start=at("2026-10-22T22:48:00Z"),end=at("2026-10-23T06:30:00Z");List<ChartTicks.Tick> ticks=ticks(start,end,UTC);assertEquals(start,ticks.get(0).time);assertEquals(end,ticks.get(ticks.size()-1).time);assertEquals(Arrays.asList("11 PM","1 AM","3 AM","5 AM"),ticks.stream().filter(t->t.endpoint==0).map(t->t.label).collect(Collectors.toList()));List<ChartTicks.Placed> placed=ChartTicks.layout(ticks,start,end,0,320,8,s->s.length()*5);assertEquals(Arrays.asList("10:48 PM","1 AM","3 AM","5 AM","6:30 AM"),placed.stream().map(p->p.tick.label).collect(Collectors.toList()));}
    @Test public void labelsKeepActualInstantsAndFollowDeviceClockFormat(){long start=at("2026-10-22T22:48:00Z"),end=at("2026-10-23T06:30:00Z");List<ChartTicks.Tick> twelve=ticks(start,end,UTC),twentyFour=ChartTicks.candidates(start,end,UTC,true,US,5);assertEquals("22:48",twentyFour.get(0).label);assertEquals("06:30",twentyFour.get(twentyFour.size()-1).label);assertTrue(twentyFour.stream().anyMatch(t->t.label.equals("01:00")));assertEquals(twelve.stream().map(t->t.time).collect(Collectors.toList()),twentyFour.stream().map(t->t.time).collect(Collectors.toList()));}
    @Test public void springGapNeverProducesAnInventedTwoAmTick(){ZoneId zone=ZoneId.of("Europe/Berlin");long start=ZonedDateTime.parse("2026-03-29T00:30:00+01:00[Europe/Berlin]").toInstant().toEpochMilli(),end=ZonedDateTime.parse("2026-03-29T05:30:00+02:00[Europe/Berlin]").toInstant().toEpochMilli();List<ChartTicks.Tick> ticks=ticks(start,end,zone);assertFalse(ticks.stream().anyMatch(t->Instant.ofEpochMilli(t.time).atZone(zone).getHour()==2));assertTrue(ticks.stream().anyMatch(t->t.label.equals("3 AM")));assertEquals(end,ticks.get(ticks.size()-1).time);}
    @Test public void repeatedHourHasTwoRealTickInstantsAndExplicitOffsets(){ZoneId zone=ZoneId.of("Europe/Berlin");long start=ZonedDateTime.parse("2026-10-25T00:30:00+02:00[Europe/Berlin]").toInstant().toEpochMilli(),end=ZonedDateTime.parse("2026-10-25T03:30:00+01:00[Europe/Berlin]").toInstant().toEpochMilli();List<ChartTicks.Tick> repeated=ticks(start,end,zone).stream().filter(t->t.endpoint==0&&Instant.ofEpochMilli(t.time).atZone(zone).getHour()==2).collect(Collectors.toList());assertEquals(2,repeated.size());assertEquals("2 AM\n+02:00",repeated.get(0).label);assertEquals("2 AM\n+01:00",repeated.get(1).label);assertEquals(3600000,repeated.get(1).time-repeated.get(0).time);}
    @Test public void rangeEntirelyInsideFoldCanIncludeEarlierWallTimeAfterItsStartInstant(){ZoneId zone=ZoneId.of("Europe/Berlin");long start=RecordDraft.instant(LocalDateTime.parse("2026-10-25T02:45"),zone,ZoneOffset.ofHours(2)),end=RecordDraft.instant(LocalDateTime.parse("2026-10-25T02:30"),zone,ZoneOffset.ofHours(1));List<ChartTicks.Tick> ticks=ticks(start,end,zone);assertTrue(ticks.stream().anyMatch(t->t.label.equals("2 AM\n+01:00")));for(ChartTicks.Tick tick:ticks)assertTrue(tick.time>=start&&tick.time<=end);assertEquals("2:30 AM +01:00",ChartTicks.tooltip(end,start,end,zone,false,US));}
    @Test public void shortSignalUsesNiceElapsedSecondsAndExactEndpoint(){long start=1234567,end=start+21321;List<ChartTicks.Tick> ticks=ticks(start,end,UTC);assertEquals("0 s",ticks.get(0).label);assertEquals("21.321 s",ticks.get(ticks.size()-1).label);assertTrue(ticks.stream().anyMatch(t->t.label.equals("5 s")));assertEquals("250 ms",ChartTicks.duration(250));assertEquals("1.999 s",ChartTicks.duration(1999));}
    @Test public void layoutNeverOverlapsLabelsAndRetainsExactEndInNarrowWidth(){long start=0,end=21000;List<ChartTicks.Placed> placed=ChartTicks.layout(ticks(start,end,UTC),start,end,20,130,8,s->s.length()*7);assertEquals(end,placed.get(placed.size()-1).tick.time);double edge=20-8;for(ChartTicks.Placed p:placed){assertTrue(p.left>=edge+8-.0001);assertTrue(p.right<=130.0001);edge=p.right;}}
    @Test public void foldLabelsMeasureTheirWidestLineRatherThanJoiningOffsets(){long start=at("2026-10-25T00:00:00Z"),end=start+3*3600000;List<ChartTicks.Placed> placed=ChartTicks.layout(ticks(start,end,ZoneId.of("Europe/Berlin")),start,end,0,400,8,s->s.length()*6);for(ChartTicks.Placed p:placed){int longest=Arrays.stream(p.tick.label.split("\n")).mapToInt(String::length).max().orElse(0);assertEquals(longest*6,p.right-p.left,.001);}}
    @Test public void multiDayRangeAddsDateToPreventAmbiguousClockLabels(){long start=at("2026-10-22T22:48:00Z"),end=at("2026-10-24T06:30:00Z");List<ChartTicks.Tick> ticks=ticks(start,end,UTC);assertEquals("10:48 PM\n22 Oct",ticks.get(0).label);assertEquals("6:30 AM\n24 Oct",ticks.get(ticks.size()-1).label);}
    @Test public void nonPositiveWindowIsEmptyAndPreEpochClockAlignmentStillWorks(){assertTrue(ticks(5,5,UTC).isEmpty());assertTrue(ticks(6,5,UTC).isEmpty());long start=at("1969-12-31T22:48:00Z"),end=at("1970-01-01T06:30:00Z");assertTrue(ticks(start,end,UTC).stream().anyMatch(t->t.label.equals("1 AM")));}
}
